using System;
using System.Collections.Generic;
using System.Linq;
using CashflowChains.Economy;
namespace CashflowChains.City {
 public static class CityDayModel {
  sealed class Pool {public string Item;public int Source,X,Y,ReadyMinute;public long Quantity;}
  static int Distance(CityProperty a,CityProperty b)=>Math.Abs(a.X-b.X)+Math.Abs(a.Y-b.Y);
  static long Scale(long value,int bp)=>checked(value*(long)bp)/10000;
  public static CityDayResult Forecast(CityCatalog catalog,CityOperatingPlan plan){
   if(plan.HousingRules==0)return LegacyCityDayModel.Forecast(catalog,plan);if(plan.Region<0||plan.Region>CityRegion.Version)throw new ArgumentException("Unknown city context");if(plan.HousingRules!=1&&plan.HousingRules!=2)throw new ArgumentException("Unknown household rules");
   var r=new CityDayResult{Day=plan.Day,Season=new[]{"SPRING","SUMMER","AUTUMN","WINTER"}[plan.HousingRules>=2?Math.Min(3,((plan.Day-1)%365)/91):((plan.Day-1)/7)%4]};var properties=plan.Properties.OrderBy(p=>p.Id).ToArray();var active=properties.Where(p=>p.Open).ToArray();r.HousingCapacity=CityPopulation.Capacity(catalog,active);r.Jobs=CityPopulation.Jobs(catalog,active);r.Population=CityPopulation.Residents(catalog,active,plan.GridTier,plan.HousingRules==1,plan.Day);var privateHouseholds=CityHousing.Occupancy(catalog,active,plan.GridTier,plan.HousingRules==1,plan.Day,plan.Region>0);r.PrivateResidents=privateHouseholds.Sum(h=>h.Residents);var publicHouseholds=plan.Region>0?CityRegion.Households(plan.Day,plan.Region,properties):new CityHouseholdOccupancy[0];r.PublicResidents=publicHouseholds.Sum(h=>h.Residents);r.PublicJobs=plan.Region>0?CityRegion.PublicEmployment:0;r.HousingCapacity+=publicHouseholds.Sum(h=>h.Units*4);var households=privateHouseholds.Concat(publicHouseholds).ToArray();r.Population=households.Sum(h=>h.Residents);r.Households=households.Sum(h=>h.Occupied);r.Adults=households.Sum(h=>h.Adults);r.Children=households.Sum(h=>h.Children);var people=households.SelectMany(h=>h.Families).SelectMany(f=>f).ToArray();r.Seniors=people.Count(p=>p.Senior);r.Workers=people.Count(p=>p.WorkingAge);if(plan.Region>=2)r.PublicJobs=r.Workers*3/4;r.Women=people.Count(p=>p.Gender=="Woman");r.Men=people.Count(p=>p.Gender=="Man");r.NonBinary=people.Count(p=>p.Gender=="Non-binary");r.JobOffers=r.Jobs;if(plan.HousingRules>=2){int available=Math.Max(0,r.Workers-r.PublicJobs);properties=properties.Select(p=>{var copy=p.Copy();int assigned=copy.Open?CityWorkforce.Staff(catalog.Business(copy.Kind),copy):0;copy.Staff=Math.Min(assigned,available);available-=copy.Staff;return copy;}).ToArray();active=properties.Where(p=>p.Open).ToArray();r.Jobs=active.Sum(p=>p.Staff);}r.PayablesDue=plan.Payables;r.LoanDue=plan.Loans.Sum(l=>l.Due(plan.Day));
   int powerMade=CityPopulation.GeneratedPower(catalog,active);r.PowerDemand=active.Sum(p=>catalog.Business(p.Kind).Power*p.Level);r.PowerAvailable=catalog.GridCapacity*plan.GridTier+powerMade;r.PowerBasisPoints=r.PowerDemand==0?10000:Math.Min(10000,r.PowerAvailable*10000/r.PowerDemand);
   r.RegionalVisitors=plan.Region>0?8:0;int transportVisitors=r.RegionalVisitors+active.Where(p=>p.Kind=="port").Sum(p=>catalog.Business(p.Kind).Tourists*p.Level),beds=active.Where(p=>p.Kind=="hotel").Sum(p=>catalog.Business(p.Kind).Sales*p.Level);r.Visitors=Math.Min(beds,(int)Scale(transportVisitors,r.Season=="SUMMER"?12500:10000));
   var market=plan.Region>0?CityRegion.Market(plan.Day):null;r.Market=market?.Name??"";r.RegionalImportCapacity=12+(market?.ExtraImportCapacity??0);int storage=catalog.BaseStorage+active.Sum(p=>catalog.Business(p.Kind).Storage*p.Level);int importCapacity=r.RegionalImportCapacity+active.Sum(p=>catalog.Business(p.Kind).ImportCapacity*p.Level),exportCapacity=active.Sum(p=>catalog.Business(p.Kind).ExportCapacity*p.Level);long importBudget=plan.CashAvailable;int suppliesReady=0;var pools=new List<Pool>();
   CityResourceResult Resource(string id){var row=r.Resources.Find(s=>s.ItemId==id);if(row==null){row=new CityResourceResult{ItemId=id};r.Resources.Add(row);}return row;}
   var store=active.Where(p=>p.Kind=="warehouse"||p.Kind=="logistics").OrderBy(p=>p.Id).FirstOrDefault();var supplyDepot=store??(plan.Region>0?CityRegion.Property(1107,plan.Region):null);foreach(var item in plan.Inventory){Resource(item.ItemId).Initial=item.Quantity;pools.Add(new Pool{Item=item.ItemId,Source=supplyDepot?.Id??0,X=supplyDepot?.X??0,Y=supplyDepot?.Y??0,Quantity=item.Quantity});}
   CityBusinessResult Business(CityProperty p){var row=r.Businesses.Find(b=>b.PropertyId==p.Id);if(row==null){row=new CityBusinessResult{PropertyId=p.Id,Kind=p.Kind};r.Businesses.Add(row);}return row;}
   bool Use(CityProperty recipient,ItemAmount[] inputs,long operations,int minute){
    suppliesReady=minute;var purchases=new List<(string Item,long Missing,int Cost)>();long total=0;
    foreach(var input in inputs){long needed=checked(input.Quantity*operations),available=pools.Where(p=>p.Item==input.ItemId).Sum(p=>p.Quantity),missing=Math.Max(0,needed-available);if(missing==0)continue;var good=catalog.Goods.FirstOrDefault(g=>g.Id==input.ItemId);if(good==null||missing>importCapacity)return false;int cost=good.ImportPrice;if(plan.Partner=="local-roaster"&&plan.Day<=plan.PartnerEndsDay&&input.ItemId=="BEANS")cost=1;long charge=checked(missing*cost);total=checked(total+charge);purchases.Add((input.ItemId,missing,cost));}
    if(total>importBudget||purchases.Sum(p=>p.Missing)>importCapacity)return false;
    foreach(var purchase in purchases){importBudget-=purchase.Missing*purchase.Cost;importCapacity-=(int)purchase.Missing;Resource(purchase.Item).Imported+=purchase.Missing;r.ImportBills+=purchase.Missing*purchase.Cost;Business(recipient).Imports+=purchase.Missing*purchase.Cost;pools.Add(new Pool{Item=purchase.Item,Source=plan.Region>0?1107:0,X=plan.Region>0?CityRegion.Property(1107,plan.Region).X:0,Y=plan.Region>0?CityRegion.Property(1107,plan.Region).Y:0,Quantity=purchase.Missing,ReadyMinute=360});}
    foreach(var input in inputs){long remaining=checked(input.Quantity*operations);foreach(var pool in pools.Where(p=>p.Item==input.ItemId&&p.Quantity>0).OrderBy(p=>Math.Abs(p.X-recipient.X)+Math.Abs(p.Y-recipient.Y)).ThenBy(p=>p.Source)){long used=Math.Min(remaining,pool.Quantity);if(used==0)continue;pool.Quantity-=used;remaining-=used;Resource(input.ItemId).Consumed+=used;int distance=Math.Abs(pool.X-recipient.X)+Math.Abs(pool.Y-recipient.Y),travel=Math.Max(1,distance*(store==null?5:3));Business(recipient).DeliveryWork+=used*distance;suppliesReady=Math.Max(suppliesReady,pool.ReadyMinute+travel);r.Flows.Add(new CityFlow{Source=pool.Source,Target=recipient.Id,Kind=input.ItemId,Count=(int)used,Minute=Math.Max(pool.ReadyMinute,minute-travel),TravelMinutes=travel});if(remaining==0)break;}if(remaining!=0)throw new InvalidOperationException("Supply allocation failed");}
    return true;
   }
   long gridBill=Scale(Math.Min(catalog.GridCapacity*plan.GridTier,Math.Max(0,r.PowerDemand-powerMade))*(long)catalog.GridUnitCost,r.Season=="WINTER"?15000:10000),allocatedPower=0;
   foreach(var p in properties){var d=catalog.Business(p.Kind);var row=Business(p);row.Employees=p.Open?CityWorkforce.Staff(d,p):0;row.Advertising=p.Open?p.MarketingBudget:0;row.Bills=p.Open?Math.Max(2,d.FixedBills-d.BaseStaff*d.DailyWage)*p.Level+row.Employees*d.DailyWage+row.Advertising:Math.Min(2,d.FixedBills)*p.Level;r.Bills+=row.Bills;if(!p.Open)continue;if(d.Rent>0){var housing=households.First(h=>h.PropertyId==p.Id);row.Households=housing.Occupied;row.Residents=housing.Residents;row.Adults=housing.Adults;row.Revenue=d.Rent*(long)housing.Occupied;r.Revenue+=row.Revenue;r.Flows.Add(new CityFlow{Source=p.Id,Target=0,Kind="RENT",Count=(int)row.Revenue,Minute=1080,TravelMinutes=1});}if(d.Power>0){long bill=gridBill*(allocatedPower+d.Power*p.Level)/r.PowerDemand-gridBill*allocatedPower/r.PowerDemand;allocatedPower+=d.Power*p.Level;row.Bills+=bill;r.Bills+=bill;}}
   // Producers operate before customer service. Inputs and outputs are finite;
   // imports reserve a published cash budget and cannot be exported for profit.
   foreach(var p in active.Where(p=>catalog.Business(p.Kind).Outputs.Length>0).OrderBy(p=>catalog.Business(p.Kind).Inputs.Length).ThenBy(p=>p.Id)){var d=catalog.Business(p.Kind);if(d.Kind=="power")continue;int operations=(int)Scale(Scale(p.Level*10000L,CityWorkforce.Productivity(d,p)),r.PowerBasisPoints)/10000;if(operations==0||!Use(p,d.Inputs,operations,420))continue;foreach(var output in d.Outputs){int season=p.Kind=="farm"?(r.Season=="WINTER"?7500:r.Season=="SPRING"?11000:10000):10000;long made=Scale(output.Quantity*operations,season);Resource(output.ItemId).Produced+=made;pools.Add(new Pool{Item=output.ItemId,Quantity=made,Source=p.Id,X=p.X,Y=p.Y,ReadyMinute=suppliesReady});}}
   var capacities=active.Where(p=>catalog.Business(p.Kind).Sales>0).ToDictionary(p=>p.Id,p=>(int)Scale(Scale(catalog.Business(p.Kind).Sales*p.Level,CityWorkforce.Productivity(catalog.Business(p.Kind),p)),r.PowerBasisPoints));
   long budget=long.MaxValue;int householdSeed=0;
   void Serve(CityProperty home,string family,int demand,int opening){
    if(demand<=0)return;if(family=="coffee")r.CoffeeDemand+=demand;var shops=active.Where(p=>catalog.Business(p.Kind).Family==family&&capacities[p.Id]>0).ToArray();if(shops.Length==0){r.CompetitorCustomers+=demand;if(plan.HousingRules>=2){int reference=catalog.Businesses.Where(b=>b.Family==family&&b.Price>0).Select(b=>b.Price).DefaultIfEmpty(0).Min();if(reference>0)budget-=Math.Min(demand,budget/reference)*reference;}return;}
    var scores=shops.ToDictionary(p=>p.Id,p=>(decimal)(10000+active.Count(a=>a.Kind=="park"&&Distance(a,p)<=2)*1000+(p.MarketingBudget==5?1500:p.MarketingBudget==15?5000:0))/(Math.Max(1,catalog.Business(p.Kind).Price*p.PriceBasisPoints/10000)*10+Distance(home,p)*5+20));decimal total=catalog.CompetitorWeight+scores.Values.Sum();int remaining=demand;
    foreach(var shop in shops.OrderBy(p=>Distance(home,p)).ThenBy(p=>p.Id)){var d=catalog.Business(shop.Kind);Business(shop).PotentialCustomers+=demand;int quantity=Math.Min(remaining,Math.Min(capacities[shop.Id],(int)Math.Floor(demand*scores[shop.Id]/total)+(plan.HousingRules>=2&&(plan.Region>0?unchecked((uint)(plan.Day*37+home.Id*19+householdSeed*23+family.Length*11))%100:((plan.Day*37+home.Id*19+householdSeed*23+family.Length*11)%100))/100m<demand*scores[shop.Id]/total-Math.Floor(demand*scores[shop.Id]/total)?1:0)));if(plan.HousingRules>=2&&plan.Day==1&&home.Id==1&&family=="coffee")quantity=Math.Min(remaining,Math.Max(quantity,1));if(quantity<=0)continue;int arrivals=opening+Distance(home,shop)*5;for(int served=0;served<quantity;served++){long value=Math.Max(1,d.Price*(long)shop.PriceBasisPoints/10000);if(plan.HousingRules>=2&&budget<value)break;if(!Use(shop,d.Inputs,1,arrivals))break;if(plan.HousingRules>=2)budget-=value;var row=Business(shop);row.Customers++;row.Revenue+=value;r.Revenue+=value;capacities[shop.Id]--;remaining--;if(family=="coffee")r.CoffeeServed++;r.Flows.Add(new CityFlow{Source=home.Id,Target=shop.Id,Kind="CUSTOMER",Count=1,Minute=opening+served*5,TravelMinutes=Distance(home,shop)*5});r.Flows.Add(new CityFlow{Source=shop.Id,Target=home.Id,Kind=family=="coffee"?"COFFEE":plan.Region>0&&family=="shopping"?"GROCERIES":"SERVICE",Count=1,Minute=Math.Max(suppliesReady,arrivals+served*5)+1,TravelMinutes=1});r.Flows.Add(new CityFlow{Source=home.Id,Target=shop.Id,Kind="CASH",Count=(int)value,Minute=Math.Max(suppliesReady,arrivals+served*5)+1,TravelMinutes=1});}}
    r.CompetitorCustomers+=remaining;if(plan.HousingRules>=2){int reference=catalog.Businesses.Where(b=>b.Family==family&&b.Price>0).Select(b=>b.Price).DefaultIfEmpty(0).Min();if(reference>0)budget-=Math.Min(remaining,budget/reference)*reference;}
   }
   int adultOffset=0;foreach(var housing in households){var home=active.FirstOrDefault(p=>p.Id==housing.PropertyId)??CityRegion.Property(housing.PropertyId,plan.Region);if(plan.HousingRules==1){int occasional=Enumerable.Range(adultOffset,housing.Adults).Count(i=>(i+plan.Day)%6==0);Serve(home,"coffee",housing.Adults,480);Serve(home,"shopping",housing.Occupied,720);Serve(home,"services",occasional,600);Serve(home,"entertainment",occasional,1140);adultOffset+=housing.Adults;continue;}
    foreach(var family in housing.Families){budget=Math.Max(0,family.Sum(p=>(long)p.DailyBudget)-catalog.Business(home.Kind).Rent);householdSeed=family[0].Id;Serve(home,"shopping",(family.Length+2)/3+(market?.ExtraShoppingNeed??0),420);Serve(home,"services",family.Count(p=>p.Adult&&(p.Id+plan.Day)%(p.Senior?6:12)==0),600);Serve(home,"coffee",family.Count(p=>p.LikesCoffee),480);Serve(home,"entertainment",family.Count(p=>p.LikesCinema&&(p.Id+plan.Day)%6==0),1140);}
   }

   if(r.Visitors>0){budget=plan.Region>0?r.Visitors*80L:long.MaxValue;var dock=active.FirstOrDefault(p=>p.Kind=="port")??CityRegion.Property(1106,plan.Region);Serve(dock,"stay",r.Visitors,900);Serve(dock,"coffee",r.Visitors/2,960);}
   if(plan.Partner=="local-roaster"&&plan.Day<=plan.PartnerEndsDay)r.Bills+=5;if(plan.Sponsor=="coffee-fair"&&plan.Day<=plan.SponsorEndsDay){r.Bills+=8;if(r.CoffeeServed>=5){r.SponsorshipRevenue=20;r.Revenue+=20;}}
   foreach(var business in r.Businesses){business.DeliveryBills=(business.DeliveryWork+(store==null?19:29))/(store==null?20:30);business.Bills+=business.DeliveryBills;r.Bills+=business.DeliveryBills;}
   foreach(var business in r.Businesses.Where(b=>b.Kind!="home")){business.Tax=Scale(business.Revenue,catalog.TaxBasisPoints);r.Tax+=business.Tax;}
   foreach(var good in catalog.Goods){var row=Resource(good.Id);long available=pools.Where(p=>p.Item==good.Id).Sum(p=>p.Quantity);long reserve=Math.Max(8,row.Consumed);long surplus=Math.Max(0,Math.Min(available-reserve,row.Initial+row.Produced-row.Consumed));long exported=good.ExportPrice<=0?0:Math.Min(exportCapacity,surplus);if(exported>0){row.Exported=exported;exportCapacity-=(int)exported;r.ExportRevenue+=exported*good.ExportPrice;r.Flows.Add(new CityFlow{Source=store?.Id??0,Target=0,Kind="EXPORT",Count=(int)exported,Minute=1200,TravelMinutes=30});available-=exported;}row.Spilled=Math.Max(0,available-storage);row.Closing=available-row.Spilled;}
   r.Revenue+=r.ExportRevenue;foreach(var row in r.Resources.Where(x=>!catalog.Goods.Any(g=>g.Id==x.ItemId)))row.Closing=row.Initial+row.Produced+row.Imported-row.Consumed-row.Exported-row.Spilled;
   foreach(var row in r.Resources)if(row.Initial+row.Produced+row.Imported!=row.Consumed+row.Exported+row.Spilled+row.Closing||row.Closing<0)throw new InvalidOperationException("City resources not conserved");return r;
  }
 }
